styles.content:
/* 浅色主题 */
:root {
    --bg: #ffffff;
    --panel: #f8f9fa;
    --card: #f0f1f3;
    --border: #e0e0e0;
    --text: #222222;
    --text2: #666666;
    --text3: #999999;
    --accent: #0891b2;
    --red: #dc2626;
    --orange: #ea580c;
    --green: #16a34a;
    --blue: #2563eb;
    --font: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
    --mono: 'Cascadia Code', 'Consolas', monospace;
    --avatar-status-color: var(--green);
}

/* 页面根容器 */
#sim-app {
    color: var(--text);
    font-family: var(--font);
    font-size: 14px;
}

/* 浮动面板 */
.sim-panel {
    width: 360px;
    max-width: 100vw;
    height: 720px;
    max-height: 100vh;
    display: flex;
    flex-direction: column;
    padding: 14px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, .08);
}

/* 身份卡 */
.profile-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 12px 14px;
    margin-bottom: 14px;
    background: rgba(8, 145, 178, .04);
    border: 1px solid rgba(8, 145, 178, .15);
    border-radius: 10px;
}

.profile-avatar {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    border: 2px solid var(--border);
    border-radius: 4px;
}

.profile-avatar::after {
    content: '';
    position: absolute;
    top: -9px;
    left: -9px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--avatar-status-color);
    border: 2px solid var(--panel);
    animation: pulse-dot 2s ease-in-out infinite;
}

.profile-avatar-img {
    display: block;
    width: 128px;
    height: auto;
}

.profile-avatar-fallback {
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--accent);
    color: #fff;
    font-size: 24px;
    font-weight: 700;
    font-family: var(--mono);
}

.profile-info {
    flex: 1;
    min-width: 0;
    position: relative;
    padding-left: 10px;
}

.profile-info::before {
    content: '';
    position: absolute;
    left: 0;
    top: 4px;
    bottom: 4px;
    width: 2px;
    background-color: var(--accent);
    border-radius: 1px;
}

@keyframes pulse-dot {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: .3;
    }
}

.profile-name {
    font-size: 16px;
    font-weight: 700;
    color: var(--text);
    letter-spacing: 1px;
}

.profile-desc {
    font-size: 11px;
    color: var(--text2);
    margin-top: 6px;
}

/* 属性卡片 */
.property-card {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.property-items {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 6px;
    flex: 1;
}

.property-item {
    display: flex;
    align-items: center;
    gap: 8px;
}

.property-label {
    width: 32px;
    font-size: 12px;
    font-weight: 600;
    color: var(--accent);
    text-align: right;
    flex: none;
    font-family: var(--mono);
}

.property-progress {
    flex: 1;
    height: 4px;
    background: var(--card);
    border-radius: 1px;
    overflow: hidden;
    position: relative;
}

.property-progress::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 0;
    width: 1px;
    height: 100%;
    background: var(--border);
    transform: translateX(-0.5px);
}

.property-progress-bar {
    position: absolute;
    left: 50%;
    top: 0;
    height: 100%;
    width: calc(var(--percentage, 0) * 0.5%);
    background: linear-gradient(90deg, var(--blue), var(--accent));
    border-radius: 0 4px 4px 0;
    transition: width .3s;
}

.property-progress-bar.reverse {
    left: auto;
    right: 50%;
    background: linear-gradient(270deg, var(--red), #fca5a5);
    border-radius: 4px 0 0 4px;
}

.property-value {
    width: 36px;
    font-size: 13px;
    font-weight: 700;
    color: var(--text);
    text-align: right;
    font-family: var(--mono);
    flex: none;
}

/* 雷达图容器 */
.property-radar {
    width: 200px;
    height: 200px;
    align-self: center;
}

/* ===== 角色列表 ===== */
.charas-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.chara-relation {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    background: rgba(255, 255, 255, .5);
    white-space: nowrap;
}

.chara-status-tag {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    background: rgba(255, 255, 255, .4);
    white-space: nowrap;
}

.chara-empty {
    text-align: center;
    padding: 30px 20px;
    color: var(--text3);
}

.chara-empty-icon {
    font-size: 36px;
    margin-bottom: 8px;
    opacity: .4;
}

.chara-empty-text {
    font-size: 13px;
}

/* ===== 建筑总览 ===== */
.build-root {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.build-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}

.build-filter-btn {
    padding: 4px 10px;
    font-size: 11px;
    font-family: inherit;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: transparent;
    color: var(--text2);
    cursor: pointer;
    transition: all .15s;
    white-space: nowrap;
}

.build-filter-btn:hover {
    color: var(--text);
    background: var(--card);
}

.build-filter-btn.active {
    border-color: var(--accent);
    color: var(--accent);
    background: rgba(8, 145, 178, .06);
}

.build-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.build-type-dot {
    flex: none;
    font-size: 16px;
    line-height: 1;
}


.build-level {
    flex: none;
    font-size: 10px;
    font-weight: 700;
    font-family: var(--mono);
    color: var(--text3);
    background: var(--panel);
    padding: 1px 6px;
    border-radius: 4px;
}

.build-status-tag {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    white-space: nowrap;
}

.build-desc {
    font-size: 12px;
    color: var(--text2);
    line-height: 1.7;
    padding: 8px 10px;
    background: rgba(0, 0, 0, .02);
    border-radius: 6px;
    border-left: 2px solid var(--accent);
}

.build-empty {
    text-align: center;
    padding: 30px 20px;
    color: var(--text3);
}

/* ===== 物品 ===== */
.item-status-tag {
    flex: none;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border: 1px solid;
    border-radius: 4px;
    white-space: nowrap;
}

scripts.content:
import {h} from 'preact';
import {useState} from 'preact/hooks';

const {STab, SFloating, SRadarChart, SExpand, SVariableImage} = window.sComponents;
const {get, useMessageData, appendItemInput, renderComponent} = window.sUtils;

function getProperties(chara) {
    const p = chara.property ?? {
        str: 0, dex: 0, con: 0,
        int: 0, wis: 0, cha: 0,
    };
    return [
        {id: 'str', name: '力量', value: p.str ?? 0},
        {id: 'dex', name: '敏捷', value: p.dex ?? 0},
        {id: 'con', name: '体质', value: p.con ?? 0},
        {id: 'int', name: '智力', value: p.int ?? 0},
        {id: 'wis', name: '感知', value: p.wis ?? 0},
        {id: 'cha', name: '魅力', value: p.cha ?? 0},
    ];
}

// ============================================================
// 个人状态 — 身份卡
// ============================================================
function ProfileCard({chara}) {
    const staColor = getStatusColor(chara.status);
    return h('div', {
        className: 'profile-card',
        style: {'--avatar-status-color': staColor}
    }, [
        h('div', {className: 'profile-avatar'},
            h(SVariableImage, {
                className: 'profile-avatar',
                name: `avatar-${chara.name}`,
                defaultComponent: () => {
                    h('span', {className: 'profile-avatar-fallback'},
                        chara.name?.[0] || '?'
                    )
                }
            }),
        ),
        h('div', {className: 'profile-info'},
            h('div', {className: 'profile-name'},
                chara.name
            ),
            h('div', {className: 'profile-desc'},
                chara.desc
            ),
        ),
    ]);
}

// ============================================================
// 个人状态 — 属性卡片（六维 + 雷达图）
// ============================================================
function PropertyCard({chara}) {
    const properties = getProperties(chara);
    const max = properties.reduce((max, current) =>
        Math.max(Math.abs(current.value) + 1, max), 1);
    const min = properties.reduce((min, current) =>
        Math.min(Math.abs(current.value), min), max);
    return h('div', {className: 'property-card'},
        h('div', {className: 'property-items'},
            properties.map((p) => {
                    return h('div', {className: 'property-item', key: p.id},
                        h('div', {className: 'property-label'}, p.name),
                        h('div', {
                                className: 'property-progress',
                                style: {
                                    '--percentage': Math
                                        .abs(100 * p.value / max)
                                        .toFixed(2)
                                }
                            },
                            h('div', {className: `property-progress-bar${p.value < 0 ? " reverse" : ""}`}),
                        ),
                        h('div', {className: 'property-value'}, p.value),
                    );
                }
            ),
        ),
        h('div', {className: 'property-radar'},
            h(SRadarChart, {items: properties, max: max, min: min * 0.9})
        )
    );
}

// ============================================================
// Tab: 🩺 个人状态
// ============================================================
function PropertyTabContent({user}) {
    return [
        h(ProfileCard, {chara: user}),
        h(PropertyCard, {chara: user}),
    ];
}

// ============================================================
// Tab: 👥 角色列表 — 角色卡片
// ============================================================

function getRelationColor(status) {
    return {
        '友好': 'var(--green)',
        '中立': 'var(--blue)',
        '敌对': 'var(--red)',
    }[status] ?? 'var(--text2)';
}

function getStatusColor(status) {
    return {
        '健康': '#16a34a',
        '危险': '#ea580c',
        '死亡': '#dc2626',
    }[status] ?? 'var(--text3)';
}


function CharaCard({chara}) {
    const relColor = getRelationColor(chara.relation);
    const staColor = getStatusColor(chara.status);

    return h(SExpand, {
        className: 'chara-card',
        header: () => [
            h('span', {className: 's-card-title'}, chara.name),
            chara.relation
                ? h('span', {
                    className: 'chara-relation',
                    style: {color: relColor, borderColor: relColor}
                }, chara.relation)
                : null,
            h('span', {
                className: 'chara-status-tag',
                style: {color: staColor, borderColor: staColor}
            }, chara.status ?? "未知"),
            h('button', {
                className: 's-card-add',
                onClick: (e) => {
                    e.stopPropagation();
                    appendItemInput(chara);
                }
            }, '✚'),
        ],
        children: () => [
            h(ProfileCard, {chara}),
            h('div', {className: "build-desc"}, chara.statusDesc),
            h(PropertyCard, {chara}),
        ],
    });
}

function CharasTabContent({charas}) {
    const entries = Object.entries(charas || {});
    if (entries.length === 0) {
        return h('div', {className: 'chara-empty'},
            h('div', {className: 'chara-empty-icon'}, '👥'),
            h('div', {className: 'chara-empty-text'}, '暂无角色信息'),
        );
    }
    return h('div', {className: 'charas-list'},
        entries.map(([name, data]) =>
            h(CharaCard, {chara: data, key: name})
        ),
    );
}

// ============================================================
// Tab: 🏗️ 建筑总览
// ============================================================

function getBuildTypeStyle(type) {
    const t = (type || '').trim();
    const rules = [
        {match: /居住|房屋|宿舍|帐篷/, icon: '🏠', color: 'var(--green)'},
        {match: /生产|工坊|制造|熔炉|厨房/, icon: '🔧', color: 'var(--orange)'},
        {match: /仓储|仓库|地窖/, icon: '📦', color: '#ca8a04'},
        {match: /防御|哨塔|围墙|陷阱|堡垒/, icon: '🛡️', color: 'var(--red)'},
        {match: /农业|菜园|种植|养殖|农场/, icon: '🌾', color: '#8b5cf6'},
        {match: /医疗|诊所|药房/, icon: '🏥', color: 'var(--blue)'},
        {match: /研究|实验室|图书馆/, icon: '🔬', color: '#a855f7'},
        {match: /探索|通讯|侦察|无线电/, icon: '📡', color: '#06b6d4'},
    ];
    for (const r of rules) {
        if (r.match.test(t)) return {icon: r.icon, color: r.color};
    }
    return {icon: '🏗️', color: 'var(--text3)'};
}

function getBuildStatusStyle(status) {
    const s = (status || '').trim();
    const rules = [
        {match: /运作中|正常|健康/, color: 'var(--green)', bg: 'rgba(22,163,74,.12)'},
        {match: /建设中|建造中|施工/, color: '#ca8a04', bg: 'rgba(202,138,4,.12)'},
        {match: /损坏|破损|坍塌/, color: 'var(--red)', bg: 'rgba(220,38,38,.12)'},
        {match: /闲置|空闲|无人|休眠/, color: 'var(--text3)', bg: 'rgba(0,0,0,.04)'},
    ];
    for (const r of rules) {
        if (r.match.test(s)) return {color: r.color, bg: r.bg};
    }
    return {color: 'var(--text3)', bg: 'rgba(0,0,0,.04)'};
}

function BuildingCard({data}) {
    const typeSty = getBuildTypeStyle(data.type);
    const statSty = getBuildStatusStyle(data.status);
    const lv = data.level ? `Lv.${data.level}` : '';

    return h(SExpand, {
        className: 'build-card',
        header: () => [
            h('span', {className: 'build-type-dot', style: {color: typeSty.color}}, typeSty.icon),
            h('span', {className: 's-card-title'}, data.name || '未命名'),
            lv ? h('span', {className: 'build-level'}, lv) : null,
            h('span', {
                className: 'build-status-tag',
                style: {color: statSty.color, background: statSty.bg, borderColor: statSty.color}
            }, data.status || '未知'),
            h('button', {
                className: 's-card-add',
                onClick: (e) => {
                    e.stopPropagation();
                    appendItemInput(data);
                }
            }, '✚'),
        ],
        children: () =>
            data.desc ? h('div', {className: 'build-desc'}, data.desc) : null,
    });
}

function BuildingTabContent({buildings}) {
    const [filter, setFilter] = useState('*');
    const entries = Object.entries(buildings || {});
    const filtered = filter === '*'
        ? entries
        : entries.filter(([, v]) => {
            const t = (v.type || '').trim();
            if (filter === '其他') {
                const known = /居住|生产|仓储|防御|农业|医疗|研究|探索/;
                return !known.test(t);
            }
            return t.includes(filter) || t === filter;
        });

    const filterTabs = [
        {key: '*', label: '全部'},
        {key: '居住', label: '🏠 居住'},
        {key: '生产', label: '🔧 生产'},
        {key: '仓储', label: '📦 仓储'},
        {key: '防御', label: '🛡️ 防御'},
        {key: '农业', label: '🌾 农业'},
        {key: '医疗', label: '🏥 医疗'},
        {key: '研究', label: '🔬 研究'},
        {key: '其他', label: '… 其他'},
    ];

    if (entries.length === 0) {
        return h('div', {className: 'build-empty'},
            h('div', {className: 'chara-empty-icon'}, '🏗️'),
            h('div', {className: 'chara-empty-text'}, '尚未建造任何设施'),
        );
    }

    return h('div', {className: 'build-root'},
        h('div', {className: 'build-filters'},
            filterTabs.map(f =>
                h('button', {
                    key: f.key,
                    className: `build-filter-btn${filter === f.key ? ' active' : ''}`,
                    onClick: () => setFilter(f.key),
                }, f.label)
            ),
        ),
        h('div', {className: 'build-list'},
            filtered.map(([name, data]) =>
                h(BuildingCard, {data, key: name})
            ),
        ),
    );
}

// ============================================================
// Tab: 🎒 物品
// ============================================================

function getItemTypeStyle(type) {
    const t = (type || '').trim();
    const rules = [
        {match: /食物|水|罐头|粮食|食材/, icon: '🍖', color: 'var(--orange)'},
        {match: /医疗|药品|急救|药/, icon: '💊', color: 'var(--red)'},
        {match: /武器|弹药|刀|枪|棍/, icon: '🔫', color: 'var(--text2)'},
        {match: /工具|零件|材料/, icon: '🔧', color: 'var(--blue)'},
        {match: /衣物|护甲|背包|鞋/, icon: '👕', color: '#06b6d4'},
        {match: /书籍|日记|地图|文件|笔记/, icon: '📖', color: '#8b5cf6'},
    ];
    for (const r of rules) {
        if (r.match.test(t)) return {icon: r.icon, color: r.color};
    }
    return {icon: '📦', color: 'var(--text3)'};
}

function getItemStatusStyle(status) {
    const s = (status || '').trim();
    const rules = [
        {match: /剩|有|还够|足够|满|多|余/, color: 'var(--green)', bg: 'rgba(22,163,74,.12)'},
        {match: /半|一点|不多|少|缺|些许/, color: '#ca8a04', bg: 'rgba(202,138,4,.12)'},
        {match: /尽|没|空|即将|快|损|坏|锈|松/, color: 'var(--red)', bg: 'rgba(220,38,38,.12)'},
    ];
    for (const r of rules) {
        if (r.match.test(s)) return {color: r.color, bg: r.bg};
    }
    return {color: 'var(--text3)', bg: 'rgba(0,0,0,.04)'};
}

function ItemCard({data}) {
    const typeSty = getItemTypeStyle(data.type);
    const statSty = data.status ? getItemStatusStyle(data.status) : null;

    return h(SExpand, {
        className: 'item-card',
        header: () => [
            h('span', {style: {color: typeSty.color}}, typeSty.icon),
            h('span', {className: 's-card-title'}, data.name || '未命名'),
            data.status
                ? h('span', {
                    className: 'item-status-tag',
                    style: {color: statSty.color, background: statSty.bg, borderColor: statSty.color}
                }, data.status)
                : null,
            h('button', {
                className: 's-card-add',
                onClick: (e) => {
                    e.stopPropagation();
                    appendItemInput(data);
                }
            }, '✚'),
        ],
        children: () =>
            data.desc ? h('div', {className: 'build-desc'}, data.desc) : null,
    });
}

function ItemTabContent({items}) {
    const entries = Object.entries(items || {});
    const filterTabs = [
        {key: '*', label: '全部'},
        {key: '食物', label: '🍖 食物'},
        {key: '医疗', label: '💊 医疗'},
        {key: '武器', label: '🔫 武器'},
        {key: '工具', label: '🔧 工具'},
        {key: '其他', label: '… 其他'},
    ];

    if (entries.length === 0) {
        return h('div', {className: 'build-empty'},
            h('div', {className: 'chara-empty-icon'}, '🎒'),
            h('div', {className: 'chara-empty-text'}, '背包空空如也'),
        );
    }

    const [filter, setFilter] = useState('*');
    const filtered = filter === '*'
        ? entries
        : entries.filter(([, v]) => {
            const t = (v.type || '').trim();
            if (filter === '其他') {
                const known = /食物|医疗|武器|工具/;
                return !known.test(t);
            }
            return t.includes(filter) || t === filter;
        });

    return h('div', {className: 'build-root'},
        h('div', {className: 'build-filters'},
            filterTabs.map(f =>
                h('button', {
                    key: f.key,
                    className: `build-filter-btn${filter === f.key ? ' active' : ''}`,
                    onClick: () => setFilter(f.key),
                }, f.label)
            ),
        ),
        h('div', {className: 'build-list'},
            filtered.map(([name, data]) =>
                h(ItemCard, {data, key: name})
            ),
        ),
    );
}

// ============================================================
// App
// ============================================================
function App() {
    const [variables] = useMessageData("variables");

    return SFloating({
        children: () => h(STab, {
            layout: (header, content) => h('div', {
                className: 'sim-panel',
            }, header, content),
            tabs: [
                {
                    id: "property",
                    header: () => '🩺 个人状态',
                    content: () => h(PropertyTabContent, {
                        user: get(variables, 'user', {}),
                    }),
                },
                {
                    id: "charas",
                    header: () => '👥 角色列表',
                    content: () => h(CharasTabContent, {
                        charas: get(variables, 'charas', {}),
                    }),
                },
                {
                    id: "buildings",
                    header: () => '🏗️ 建筑',
                    content: () => h(BuildingTabContent, {
                        buildings: get(variables, 'buildings', {}),
                    }),
                },
                {
                    id: "items",
                    header: () => '🎒 物品',
                    content: () => h(ItemTabContent, {
                        items: get(variables, 'items', {}),
                    }),
                },
            ],
        }),
        button: () => '🔮',
        className: "sim-floating",
    });
}

renderComponent(App, 'sim-app');

